import fs from 'node:fs';import path from 'node:path';import {createRequire} from 'node:module';
const root=path.resolve(import.meta.dirname,'../..'),require=createRequire(path.join(root,'resources/admin/package.json')),ts=require('typescript'),cache=new Map();
function load(file){file=path.resolve(file);if(file.endsWith('.json'))return {default:JSON.parse(fs.readFileSync(file,'utf8'))};if(cache.has(file))return cache.get(file);const mod={exports:{}};cache.set(file,mod.exports);const code=ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;new Function('require','exports','module',code)(p=>load(path.resolve(path.dirname(file),p.endsWith('.json')?p:p+'.ts')),mod.exports,mod);return mod.exports;}
const factory=load(path.join(root,'resources/admin/src/cms/connectedPageTemplates.ts'));
const destinations=Object.fromEntries(factory.connectedPageIds.map(id=>[id,'/pages/'+id]));
const pages=factory.connectedPageCards.map(card=>{const key=card.id.replace('jw-connected-',''),name=card.name.replace(/^JW /,'');return {key,document:{title:'{{brand}} — '+name,slug:card.id,description:'Connected website starter. Draft for review; existing pages stay unchanged.',template:'landing',heroImage:null,seoTitle:'{{brand}} — '+name,seoDescription:'',style:factory.connectedPageStyle(),containerWidth:'full',sections:factory.connectedPageSections(card.id,{shopName:'{{brand}}',connectedPageDestinations:destinations},'cms-starter-20261115-'+key)}};});
if(pages.length!==8||pages.reduce((n,p)=>n+p.document.sections.length,0)!==63)throw new Error('Unexpected starter inventory');
const output=path.join(root,'resources/cms/releases/20261115-connected-starters.json');fs.writeFileSync(output,JSON.stringify({release:'connected-starters-20261115',pages},null,2)+'\n');console.log('Exported8starters/63regions from formal factories');
